WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_boat_drift'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '漂流问题', 'kp-trv-boat-drift', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "漂流问题（草帽问题）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心推论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "在流水中，船和漂流物【相对速度】等于静水船速，与水速无关！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“某人开船，草帽掉入水中顺流漂走。半小时后发现，立刻掉头去追。多久追上？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心秒杀"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这是物理学参照系的神奇应用。假设水是静止的，草帽不动。船离开草帽开了半小时，掉头回来找草帽，由于船自己的速度不变，回来【也一定需要半小时】！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[看到船追漂流物] --> B[直接秒杀: 离开漂流物多久, 追回漂流物就需要多久]\nB --> C[完全不需要管水流速度有多快]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 逆水行船，草帽落水。船开了 20 分钟才发现，立刻掉头顺水追。多久追上草帽？"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "答案：20 分钟！秒杀。"}]}]}$$ AS jsonb), NULL, '漂流问题的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "漂流问题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_boat_drift", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
